DEFINITIONS=[{'symbol': '600082', 'primary': '1225096042', 'pages': [1, 2], 'question': '报表更正了，为什么仍需保留处罚警示？', 'risk_group': '历史虚假记载处罚与撤销门槛', 'known_at_anchor': '4月14日起其他风险警示；4月25日披露收到正式处罚决定，4月29日已披露追溯更正。2025年末内控有效意见不等于虚假记载处罚警示已解除。', 'watch': '分别核处罚决定作出日、满12个月条件、追溯重述及正式撤销；不从ST实施日倒推自动摘帽日。', 'supporting': [{'id': '1225181447', 'pages': [1, 3], 'note': '收到决定与作出决定分开；罚款400万元属公司。'}, {'id': '1225246019', 'pages': [1, 5], 'note': '追溯更正已披露，不代表时间门槛与正式批准完成。'}, {'id': '1225246007', 'pages': [2], 'note': '扫描原页内控有效意见，仅对应2025年末财报内控。'}]}, {'symbol': '600084', 'primary': '1225212709', 'pages': [1, 2], 'question': '审计意见正常，为什么仍会成为*ST？', 'risk_group': '亏损与扣除后营收组合门槛', 'known_at_anchor': '4月29日起退市风险警示；扣除后营收约1.177亿元且亏损。财报无保留与内控有效不豁免组合财务条件。', 'watch': '核年度扣除后营收、利润孰低口径与审计及正式撤销；营销和盘活计划不当已实现营收。', 'supporting': [{'id': '1225212749', 'pages': [1], 'note': '财务报表审计意见与财务退市门槛分别核。'}, {'id': '1225212727', 'pages': [2], 'note': '内控有效是另一维度。'}]}, {'symbol': '600107', 'primary': '1225264753', 'pages': [1, 2], 'question': '本金和利息已还，为什么约束还不止一项？', 'risk_group': '财务组合门槛与连续两年内控否定', 'known_at_anchor': '2025年先因内控否定成为ST；2026年5月6日起叠加亏损/低扣除后营收和连续两年内控否定的退市风险。7月3日公司回复已披露归还本金及6月30日利息，但会计师未做期后内控审计，无法确认整改有效。', 'watch': '财务组合和规范类两条约束分别核，资金归还不等于内控有效；7月3日回复仅按披露日纳入，不证明当日交易前已知。', 'supporting': [{'id': '1223419026', 'pages': [1], 'note': '原其他风险警示起点2025年5月6日。'}, {'id': '1225264720', 'pages': [2], 'note': '4月公告的本金归还声明，不把后来利息提前。'}, {'id': '1225407516', 'pages': [10, 14], 'note': '7月3日回复分列本金、利息和内控审计限制。'}]}, {'symbol': '600119', 'primary': '1225197307', 'pages': [1, 2], 'question': '旧保留事项消除了，是否就没有风险？', 'risk_group': '财务组合门槛，旧诉讼会计影响另核', 'known_at_anchor': '4月28日起退市风险警示，扣除后营收约2.025亿元且亏损。2025财报为无保留意见；董事会称旧保留事项影响已消除，但截至说明出具时诉讼仍无生效判决。', 'watch': '核年度财务条件、案件生效文书及实际责任，不把会计影响消除解释为胜诉或清偿。', 'supporting': [{'id': '1225197393', 'pages': [2], 'note': '扫描原页显示财报无保留，仍有财务组合约束。'}, {'id': '1225197559', 'pages': [3, 4], 'note': '董事会专项说明与案件终局分别核，声明不能当法院判决。'}]}]
